    }
{code}

org.eclipse.jetty.ee10.servlet.ServletChannel
{code:java}
    void recycle(Throwable x)
    {
        // _httpInput must be recycled before _state.
        _httpInput.recycle();
        _httpOutput.recycle();
        _state.recycle();
        _servletContextRequest = null;
        _request = null;
        _response = null;
        _callback = null;
    }
{code}

